    }
  },
  "required": [
    "id"
  ]
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "The subagent id to message."
    },
    "message": {
      "type": "string",
      "description": "The follow-up instruction or question."
    }
  },
  "required": [
    "id",
    "message"
  ]
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
