+        var mod = loadDevelopTicketAndCreatePRWithRealGitHelpers(nameProbeMock(WARNING));
+
+        var name = mod.generateUniqueBranchName('feature', 'PROJ-1');
+
+        assert.equal(name, 'feature/PROJ-1',
