+            'the create-branch path must run, got: ' + JSON.stringify(calls));
+        assert.equal(calls.indexOf('git checkout -B ai/PROJ-1 origin/ai/PROJ-1'), -1,
+            'must never checkout a tracking ref that was never fetched');
+    });
+
