+
+            var name = mod.generateUniqueBranchName('feature', 'PROJ-1');
+
+            assert.equal(name, 'feature/PROJ-1_1',
+                'a real existing branch must still trigger the collision suffix, got: ' + name);
+        });
+    });
+
+});
